-- Consolidated migration for the supplied Percona/MySQL 5.7.23 schema.
-- Stop application/worker writes and take an external backup before running.
-- Execute this whole file in HeidiSQL/MySQL, with DELIMITER support.
-- UUID defaults are generated by Sequelize; MySQL 5.7 cannot use UUID() defaults.
-- No table is truncated or dropped. Original tables, indexes, timestamps and
-- UUIDs are retained. Numeric identities and relational references are mapped.
-- DDL implicitly commits. Rerun this file to resume an interrupted migration.
-- Do not run the earlier .cjs runner as an additional migration on this schema.
-- The pasted dump already includes the brief classification and room_type_other
-- columns. The guards below also support installations missing those columns.
-- The terms/plain-text-input changes require no database column changes.

USE `spsyn8lm_rippotai_erp`;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `_uuid_pk_id_map` (
  `table_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `old_id` varchar(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `uuid_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  PRIMARY KEY (`table_name`, `old_id`), KEY `idx_uuid_map_new` (`table_name`, `uuid_id`)
) ENGINE=InnoDB;

-- Only needed if workflow rows reference legacy INTEGER project IDs.
-- Populate verified old-project -> existing projects.id values before CALL below.
-- Never guess them from project names or the example/demo ordering.
CREATE TABLE IF NOT EXISTS `_uuid_project_id_map` (
  `old_id` varchar(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `project_id` char(36) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  PRIMARY KEY (`old_id`)
) ENGINE=InnoDB;
