CREATE TABLE IF NOT EXISTS `_uuid_20261006_state` (
  `id` tinyint NOT NULL PRIMARY KEY,
  `status` varchar(20) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `_uuid_20261006_targets` (
  `table_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL PRIMARY KEY,
  `row_count` bigint unsigned DEFAULT NULL,
  `backup_done` tinyint NOT NULL DEFAULT 0,
  `convert_pk` tinyint NOT NULL DEFAULT 1
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `_uuid_20261006_refs` (
  `table_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `source_column` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `target_column` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `parent_table` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `filter_column` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `filter_value` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `nullable` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`table_name`, `target_column`)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `_uuid_20261006_fks` (
  `table_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `constraint_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `restore_sql` text NOT NULL,
  PRIMARY KEY (`table_name`, `constraint_name`)
) ENGINE=InnoDB;

DELIMITER $$
DROP PROCEDURE IF EXISTS `_uuid57_exec`$$
CREATE PROCEDURE `_uuid57_exec`(IN p_sql LONGTEXT)
BEGIN
  SET @uuid57_sql = p_sql;
  PREPARE uuid57_stmt FROM @uuid57_sql;
  EXECUTE uuid57_stmt;
  DEALLOCATE PREPARE uuid57_stmt;
END$$

DROP PROCEDURE IF EXISTS `_uuid57_add`$$
CREATE PROCEDURE `_uuid57_add`(IN p_table VARCHAR(64), IN p_column VARCHAR(64), IN p_definition TEXT)
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table)
     AND NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_column) THEN
    CALL _uuid57_exec(CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN `', p_column, '` ', p_definition));
  END IF;
END$$

DROP PROCEDURE IF EXISTS `_uuid57_ref`$$
CREATE PROCEDURE `_uuid57_ref`(IN p_table VARCHAR(64), IN p_snake VARCHAR(64), IN p_camel VARCHAR(64), IN p_parent VARCHAR(64), IN p_filter VARCHAR(64), IN p_value VARCHAR(64))
BEGIN
  DECLARE v_source VARCHAR(64);
  DECLARE v_nullable VARCHAR(3);
  SET v_source = NULL;
  IF EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_snake) THEN
    SET v_source = p_snake;
  ELSEIF p_camel IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_camel) THEN
    SET v_source = p_camel;
  END IF;
  IF v_source IS NOT NULL THEN
    SELECT IS_NULLABLE INTO v_nullable FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = v_source;
    INSERT IGNORE INTO _uuid_20261006_refs
      (table_name, source_column, target_column, parent_table, filter_column, filter_value, nullable)
      VALUES (p_table, v_source, p_snake, p_parent, p_filter, p_value, v_nullable);
  END IF;
END$$

DROP PROCEDURE IF EXISTS `_uuid57_rename`$$
CREATE PROCEDURE `_uuid57_rename`(IN p_table VARCHAR(64), IN p_old VARCHAR(64), IN p_new VARCHAR(64), IN p_definition TEXT)
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_old)
    AND NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_new) THEN
    CALL _uuid57_exec(CONCAT('ALTER TABLE `', p_table, '` CHANGE COLUMN `', p_old, '` `', p_new, '` ', p_definition));
  END IF;
END$$
DELIMITER ;

