CREATE TABLE IF NOT EXISTS `phases` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `name` varchar(255) NOT NULL, `code` varchar(40) NOT NULL,
  `track_type` enum('MAIN','VENDOR_TRADES','MATERIAL_PROCUREMENT') NOT NULL DEFAULT 'MAIN',
  `order` int NOT NULL, `description` text,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_workflow_phases_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `deliverables` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `step_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `name` varchar(200) NOT NULL, `description` text,
  `is_required` tinyint(1) NOT NULL DEFAULT 1, `file_type` varchar(60) DEFAULT NULL,
  `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`), KEY `idx_deliverables_step` (`step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `gate_logs` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `project_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `step_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `gate_name` varchar(150) NOT NULL, `achieved_at` datetime NOT NULL,
  `approver_team_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `approver_name` varchar(150) NOT NULL, `notes` text,
  `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`), KEY `idx_workflow_gate_project` (`project_id`),
  KEY `idx_workflow_gate_step` (`step_id`), KEY `idx_workflow_gate_team` (`approver_team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `continuity_roles` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `project_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `team_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `continuity_type` enum('CONTINUOUS','GATE_BOUND') NOT NULL DEFAULT 'CONTINUOUS',
  `opens_at_step_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `closes_at_step_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
  `actual_opened_at` datetime DEFAULT NULL, `actual_closed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`), KEY `idx_continuity_project` (`project_id`), KEY `idx_continuity_team` (`team_id`),
  KEY `idx_continuity_open_step` (`opens_at_step_id`), KEY `idx_continuity_close_step` (`closes_at_step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `project_step_progress` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `project_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `step_id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `status` enum('NOT_STARTED','IN_PROGRESS','COMPLETED','BLOCKED') NOT NULL DEFAULT 'NOT_STARTED',
