  KEY `idx_workflow_progress_step` (`step_id`), KEY `idx_workflow_progress_team` (`assignee_team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
CREATE TABLE IF NOT EXISTS `project_deliverable_records` (
  `id` char(36) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
